// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VisitorEvent) predicate.VisitorEvent {
	return predicate.VisitorEvent(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VisitorEvent) predicate.VisitorEvent {
	return predicate.VisitorEvent(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VisitorEvent) predicate.VisitorEvent {
	return predicate.VisitorEvent(sql.NotPredicates(p))
}
